cat /home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-10-projects-provenance-weight-training/1240aaf6-101c-4508-aac4-6d4b47f22c2b/tool-results/mcp-agent-ml-research-read_registry-1779167741072.txt | python3 -c "
import json, sys, re

raw = json.load(sys.stdin)
data = json.loads(raw['result'])
experiments = data['data']['experiments']

# Broader search: anything referencing cross-model, cross_model, generalization across, 3b, 3B
patterns = [r'cross.model', r'cross_model', r'3b', r'3\.2']

matching = {}
for exp_id, exp_data in experiments.items():
    full_text = json.dumps({exp_id: exp_data}, default=str).lower()
    for pat in patterns:
        if re.search(pat, full_text):
            if exp_id not in ['llama3b_adaptive_seed42', 'llama3b_uniform_seed42']:
                matching[exp_id] = exp_data
                # find the matching context
                break

print(f'Additional experiments referencing cross-model/3b/3.2: {len(matching)}')
for eid in sorted(matching.keys()):
    exp = matching[eid]
    # Print just the fields that contain the match
    full_text = json.dumps({eid: exp}, default=str)
    snippets = []
    for pat in patterns:
        for m in re.finditer(pat, full_text, re.IGNORECASE):
            start = max(0, m.start() - 80)
            end = min(len(full_text), m.end() + 80)
            snippets.append(full_text[start:end])
    print(f'  {eid} (status={exp.get(\"status\",\"?\")}):')
    for s in snippets[:3]:
        print(f'    ...{s}...')
" 2>&1

